// Parse /search <query> command forwarded from WF-01
const body = $input.item.json.body || $input.item.json;
const text = (body.text || '').trim();
const channelId = body.channel_id || '';
const userId = body.user_id || '';

// Strip /search prefix
const match = text.match(/^\/search\s+(.+)$/i);
if (!match) {
  return {
    json: {
      error: true,
      channel_id: channelId,
      message: ':x: *Uso:* `/search <consulta>`\n\nEjemplos:\n`/search espiral geometría`\n`/search exploration NEYEN`\n`/search pipeline realisation`'
    }
  };
}

const query = match[1].trim();
if (query.length < 2) {
  return {
    json: {
      error: true,
      channel_id: channelId,
      message: ':x: La consulta debe tener al menos 2 caracteres.'
    }
  };
}

return {
  json: {
    error: false,
    query: query,
    channel_id: channelId,
    user_id: userId
  }
};

// Send parse error to Slack
const d = $input.item.json;
await this.helpers.httpRequest({
  method: 'POST',
  url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
  headers: { 'Content-Type': 'application/json' },
  body: { text: d.message },
  json: true
});
return { json: { status: 'error_sent' } };

// Call search_entries() RPC
const d = $input.item.json;
const ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24';

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/search_entries',
  headers: {
    'apikey': ANON,
    'Authorization': 'Bearer ' + ANON,
    'Content-Type': 'application/json'
  },
  body: { p_query: d.query, p_limit: 5 },
  json: true
});

return {
  json: {
    ...d,
    search_result: result
  }
};

// Format search results as a Slack message
const d = $input.item.json;
const sr = d.search_result || {};
const results = sr.results || [];
const count = sr.count || 0;
const query = d.query;
const terms = (sr.terms || []).join(', ');

const ROLE_EMOJI = {
  realisation: ':bulb:', exploration: ':mag:', conflict: ':zap:',
  symbol: ':cyclone:', system: ':gear:', orphaned: ':white_circle:',
  setup: ':triangular_ruler:', integration: ':link:',
  inciting_event: ':boom:', pilot: ':rocket:'
};

if (count === 0) {
  return {
    json: {
      message: `:mag: *Sin resultados para "${query}"*\n_Términos buscados: ${terms}_\n\nPrueba con otros términos, o usa \`/graph\` para ver la distribución de roles.`,
      channel_id: d.channel_id
    }
  };
}

const lines = results.map((r, i) => {
  const emoji = ROLE_EMOJI[r.narrative_role] || ':small_blue_diamond:';
  const tags = (r.tags || []).slice(0, 4).map(t => '`' + t + '`').join(' ');
  const shortSummary = (r.summary || '').substring(0, 100);
  const linksStr = r.crosslink_count > 0 ? ` · :link: ${r.crosslink_count}` : '';
  return `*${i + 1}.* ${emoji} \`${r.file_name}\` _(${r.score}pts${linksStr})_\n    _${shortSummary}${shortSummary.length >= 100 ? '...' : ''}_\n    ${tags}`;
}).join('\n\n');

const msg = `:mag: *Búsqueda NEYEN: "${query}"*\n_${count} resultado${count !== 1 ? 's' : ''} · términos: ${terms}_\n\n${lines}\n\n_Usa \`/tag <file_name> narrative_role <role>\` para reclasificar cualquier entrada._`;

return {
  json: {
    message: msg,
    channel_id: d.channel_id
  }
};

// Post search results to Slack
const d = $input.item.json;
await this.helpers.httpRequest({
  method: 'POST',
  url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
  headers: { 'Content-Type': 'application/json' },
  body: { text: d.message },
  json: true
});
return { json: { status: 'ok', command: 'search' } };
